def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Recolor every complete zero row and complete zero column.
    rows = [r for r in range(h) if all(v == 0 for v in out[r])]
    cols = [c for c in range(w) if all(out[r][c] == 0 for r in range(h))]
    for r in rows:
        out[r] = [2] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
